public static class PrototypeBuilder {
 static Font font;
 static Sprite Art(string n){string p="Assets/Art/"+n+".png";var i=AssetImporter.GetAtPath(p) as TextureImporter;if(i==null)return null;i.textureType=TextureImporterType.Sprite;i.alphaIsTransparency=true;i.SaveAndReimport();return AssetDatabase.LoadAssetAtPath<Sprite>(p);}
